            }
          ],
          "items": {
            "type": "object",
            "description": "日程项",
            "sampleValue": {
              "entityId": "calendar_sample_001",
              "title": "产品评审",
              "eventLocation": "3F 会议室",
              "dtStart": "09:30",
              "dtEnd": "10:00"
            },
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符",
                "sampleValue": "calendar_sample_001"
              },
              "title": {
                "type": "string",
                "description": "日程标题",
                "sampleValue": "产品评审"
              },
              "eventLocation": {
                "type": "string",
                "description": "日程发生的位置",
                "sampleValue": "3F 会议室"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间，当天事件使用 HH:MM",
                "sampleValue": "09:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间，当天事件使用 HH:MM",
                "sampleValue": "10:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_schedule.png",
      "description": "日程图标，适合用于当下日程或日历事件识别。"
    }
  ]
}

